# Try to add more edges greedily while preserving girth >= 7
from collections import defaultdict, deque

n = 24
edges = [(i, (i+1)%n) for i in range(n)]  # 24-cycle
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

def dist(adj, s, t, limit):
    # BFS up to limit
    dist = {s:0}
    q = deque([s])
    while q:
        u = q.popleft()
        if dist[u] >= limit: continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u]+1
                if v == t: return dist[v]
                q.append(v)
    return dist.get(t, float('inf'))

# Try adding each possible edge
import random
random.seed(1)
candidates = [(u,v) for u in range(n) for v in range(u+1,n) if v not in adj[u]]
random.shuffle(candidates)

for u,v in candidates:
    # adding (u,v) creates a cycle of length 1 + dist(u,v). Need >=7, so dist(u,v) >= 6
    d = dist(adj, u, v, 6)
